ALL = MINE + "oZsFyPGij0U -6pe_zOKCig Q3i3FOC-dPE teg9SfzpMy0 1nt8hK2oYrE K5a7C4b1Cwc o4rMbhsdk0I pcp9h_M6Ir8 JHgeEo3n1do JjeFktc4QLM an7u-tVP5Xc".split()
