    for i in range(1, len(parts), 2):
        blocks[ts(parts[i])] = parts[i+1]
    trans[vid] = (t, blocks)
    print(vid, "last marker", max(blocks) // 60, ":", max(blocks) % 60, "nblocks", len(blocks))
