    keys = re.findall(r"^([a-z-]+):", fm, re.M)
    exp = ["type","kind","domain","book","chapter","topic","category","confidence","ingest-tier","created","source"]
    if keys != exp: issues.append(f"keys {keys}")
    kind = re.search(r"^kind:\s*(\S+)", fm, re.M).group(1)
    if not bn.startswith(kind+"--"): issues.append("kind/prefix mismatch")
    conf = re.search(r"^confidence:\s*(\S+)", fm, re.M).group(1)
    if conf not in ("supported","untested","contested"): issues.append("conf "+conf)
    if not re.search(r'^chapter: "', fm, re.M): issues.append("chapter not quoted")
    if "created: 2026-10-01" not in fm: issues.append("created")
    body = txt.split("---",2)[2]
    for h in ["What it is","Why it works","When to apply","When NOT to apply","Example","Related"]:
        if f"**{h}** —" not in body: issues.append("hdr "+h)
    b2 = re.sub(r"\*\*[^*]+\*\* —", "", body)
    if "—" in b2: issues.append("em dash in body")
    if re.search(r"prior version|corrected from|NO-GO|review round|reviewer", body, re.I): issues.append("review history phrase")
    for l in re.findall(r"\[\[([^\]|#]+)", body):
        l2 = l.split("/")[-1]
        if l2 not in names: issues.append("link? "+l)
    # locators
    for vid in ids:
        if vid not in MINE: continue
        blocks = trans[vid][1]
        for mm in re.finditer(re.escape(vid)+r"\s*\[(\d+:\d{2})\]((?:\s*(?:to|,|and|-)\s*\[\d+:\d{2}\])*)", body):
            locs = [mm.group(1)] + re.findall(r"\[(\d+:\d{2})\]", mm.group(2))
            for loc in locs:
                if ts(loc) not in blocks: issues.append(f"loc {vid} [{loc}] not a marker")
        # bare [mm:ss] not preceded by id
    for mm in re.finditer(r"(?<![A-Za-z0-9_-] )(?<!\w)\[(\d+:\d{2})\]", body):
        pass
    print(f"{ch}|{bn}|{conf}|ids={' '.join(ids)}|{'; '.join(issues) if issues else 'ok'}")

